import{_ as s,o as t,c as a,a3 as o}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Status","description":"","frontmatter":{},"headers":[],"relativePath":"run/status.md","filePath":"run/status.md"}'),r={name:"run/status.md"};function n(i,e,c,d,h,l){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h1><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>It prints, in this order:</p><ul><li>the installed version and the address Wake serves;</li><li>the people the free plan counts, such as <code>People: 2 of 3 (free plan)</code>, or <code>People: unknown</code> when the server cannot answer (see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a>);</li><li>how many backups <code>backups/</code> holds, the space they use and where they are, such as <code>Backups: 2 using 1.2 GiB in /home/you/wake-server/backups</code>, or <code>Backups: none</code>;</li><li>each service&#39;s health: <code>postgres</code>, <code>minio</code>, <code>server</code>, <code>web</code> and <code>caddy</code>;</li><li>whether a newer stable release exists, with the command that upgrades to it.</li></ul><p>When Docker is not running, it prints the first three lines, then <code>! Docker is not running: start it with wake-server start</code>, and exits <code>1</code>. When every service is stopped it says to run <code>wake-server start</code>. When GitHub cannot be reached it says the newest release is unknown, and still exits <code>0</code>.</p><p><code>wake-server status</code> asks GitHub for the newest release itself, even when the server&#39;s own <a href="/wake-dist/docs/run/upgrade#how-you-hear-of-a-new-release">update check</a> is off.</p><h2 id="from-a-repository" tabindex="-1">From a repository <a class="header-anchor" href="#from-a-repository" aria-label="Permalink to &quot;From a repository&quot;">​</a></h2><p>In a repository connected to this installation, <code>wake doctor</code> checks the connection, your login, the server&#39;s version and every connected agent, and names the fix for each failed check. When the server cannot be reached and it is the one the installer recorded on this machine, the fix is <code>wake-server start</code>. See <a href="/wake-dist/docs/reference/troubleshooting">Troubleshooting</a>.</p>',8)])])}const k=s(r,[["render",n]]);export{u as __pageData,k as default};
